148	// buildRetrievalOptions validates and assembles the shared retrieval-options
149	// contract from CLI flags. branch doubles as the conversation
150	// branch filter; error text names bare flag words so the CLI can prefix "--".
151	func buildRetrievalOptions(source, after, before, session, agent, branch string, concepts []string) (retrievalOptions, error) {
152		parsedSource, err := retrieval.ParseSource(source)
153		if err != nil {
154			return retrievalOptions{}, err
155		}
156		if len(concepts) > conversationConceptsMaxTotal-1 {
157			return retrievalOptions{}, fmt.Errorf("concept: at most %d additional concepts (got %d)", conversationConceptsMaxTotal-1, len(concepts))
158		}
159		trimmedConcepts := make([]string, 0, len(concepts))
160		for _, concept := range concepts {
161			concept = strings.TrimSpace(concept)
162			if concept == "" {
163				return retrievalOptions{}, fmt.Errorf("concept: concepts must be non-empty")
164			}
165			trimmedConcepts = append(trimmedConcepts, concept)
166		}
167		if len(trimmedConcepts) > 0 && parsedSource != brainstore.RetrievalSourceConversation {
168			return retrievalOptions{}, fmt.Errorf(`concept: concepts require source "conversation" (got %q)`, parsedSource)
169		}
170		afterTime, err := retrieval.ParseTimeFilter(after)
171		if err != nil {
172			return retrievalOptions{}, fmt.Errorf("after: %s", err.Error())
173		}
174		beforeTime, err := retrieval.ParseTimeFilter(before)
175		if err != nil {
176			return retrievalOptions{}, fmt.Errorf("before: %s", err.Error())
177		}
178		if !afterTime.IsZero() && !beforeTime.IsZero() && !afterTime.Before(beforeTime) {
179			return retrievalOptions{}, fmt.Errorf("after (%s) must be earlier than before (%s)", after, before)
180		}
181		return retrievalOptions{
182			Source:    parsedSource,
183			After:     afterTime,
184			Before:    beforeTime,
185			SessionID: strings.TrimSpace(session),
186			Agent:     strings.TrimSpace(agent),
187			Branch:    strings.TrimSpace(branch),
188			Concepts:  trimmedConcepts,
189		}, nil
190	}
191	
192	// surface names the read surface for serve receipts ("search"/"vsearch"/
193	// "query"). ropts carries the
194	// validated source selector and structured filters; branch (the raw flag)
195	// still selects the facts branch via resolveFactsTarget.
196	func runRetrieve(ctx context.Context, cmd *cobra.Command, opts Options, query string, mode retrievalMode, limit int, branch string, ropts retrievalOptions, jsonOut, patterns bool, surface string) error {
197		// Reject --limit <= 0 rather than silently defaulting, so a typo like
198		// `--limit 0` is an explicit error (matching the rest of the CLI surface).
199		if limit <= 0 {
200			return fmt.Errorf("--limit must be greater than 0")
201		}
202		if len(ropts.Concepts) > 0 {
203			if err := validateRetrievalLimit(limit); err != nil {
204				return fmt.Errorf("--%s", err.Error())
205			}
206		}
207		repoDir, brainDir, resolvedBranch, err := resolveFactsTarget(ctx, opts, agentSurfaceTarget(opts, nil), branch)
208		if err != nil {
209			return err
210		}
211		privacyPolicy, err := brainstore.CaptureRetrievalPrivacyPolicy(brainDir)
212		if err != nil {
213			return err
214		}
215		if patterns {
216			privacyPolicy.RequireDerivedClean = true
217			if err := requirePrivacyDerivedRead(brainDir); err != nil {
218				return err
219			}
220			if err := requirePatternCorpusAvailable(brainDir); err != nil {
221				return err
222			}
223		}
224		// Facts recorded outside any repository merge into the fact layer before
225		// ranking, so a preference recorded once applies on every retrieval surface
226		// rather than only on the one command that happened to load them. They go
227		// through the same guard, filters and scoring as repository facts.
228		if globalFacts, globalErr := globalFactsForRead(opts.Env, ropts.NoGlobalFacts); globalErr != nil {
229			fmt.Fprintf(cmd.ErrOrStderr(), "warning: global memories unavailable: %v\n", globalErr)
230		} else {
231			ropts.GlobalFacts = globalFacts
232		}
233		results, err := retrieveUnifiedWithOptions(repoDir, brainDir, resolvedBranch, query, limit, mode, ropts)
234		if err != nil {
235			return err
236		}
237		multiConcept := len(ropts.Concepts) > 0
238		policyIdentityBeforeExtras := privacyPolicy.Identity
239		factIDs := unifiedFactIDs(results)
240		recordReceipt := func() {
241			recordServedFacts(cmd.ErrOrStderr(), vitalityNow(opts), brainDir, resolvedBranch, surface,
242				vitalityHead(ctx, opts.Runner, repoDir), query, factIDs)
243		}
244		// Discoverability only: pattern/theme pointers never enter the facts/history/
245		// docs ranking — they are a separate, capped, opt-in section so default
246		// retrieval quality is unchanged by construction.
247		var related []relatedPatternRef
248		if patterns {
249			related, err = relatedPatternPointersChecked(brainDir, query, patternPointerCap)
250			if err != nil {
251				return err
252			}
253		}
254		var abstractPreviews []sessionAbstractPreview
255		var abstractPreviewsTruncated bool
256		if ropts.IncludeAbstract {
257			if ropts.Source != brainstore.RetrievalSourceConversation {
258				return fmt.Errorf(`--include-abstract requires --source conversation (got %q)`, ropts.Source)
259			}
260			abstractPreviews, abstractPreviewsTruncated, err = abstractPreviewsForResults(brainDir, results)
261			if err != nil {
262				return err
263			}
264		}
265		if !multiConcept {
266			// Preserve the pre-multi-concept payload byte-for-byte, but buffer it so the shared
267			// final privacy check runs after assembly and before the first write. The
268			// 128 KiB response contract and proof rendering still belong only to
269			// multi-concept coverage.
270			if jsonOut {
271				out := map[string]any{"query": query, "branch": resolvedBranch, "results": compactUnifiedResults(results, query)}
272				if ropts.IncludeAbstract {
273					out["abstract_previews"] = abstractPreviews
274					out["abstract_previews_truncated"] = abstractPreviewsTruncated
275				}
276				hints := retrievalHintsForResults(repoDir, results, query)
277				if len(hints.LikelyEditFiles) > 0 {
278					out["likely_edit_files"] = hints.LikelyEditFiles
279				}
280				if len(hints.LikelyTestFiles) > 0 {
281					out["likely_test_files"] = hints.LikelyTestFiles
282				}
283				if len(hints.ActionChecklist) > 0 {
284					out["action_checklist"] = hints.ActionChecklist
285				}
286				if len(related) > 0 {
287					out["related_patterns"] = related
288				}
289				if len(results) == 0 {
290					if note := emptyResultBlindSpotOnBranch(brainDir, resolvedBranch); note != "" {
291						out["blind_spot"] = note
292					}
293				}
294				serialized, err := jsonOutputBytes(out)
295				if err != nil {
296					return err
297				}
298				if err := writeRetrievalResponseBytes(cmd.OutOrStdout(), serialized, privacyPolicy); err != nil {
299					return err
300				}
301				if len(factIDs) > 0 {
302					recordReceipt()
303				}
304				return nil
305			}
306			var rendered bytes.Buffer
307			if err := cmdutil.WriteTextToWriter(&rendered, func(out io.Writer) {
308				if len(results) == 0 {
309					fmt.Fprintf(out, "no results for %q\n", query)
310					if note := emptyResultBlindSpotOnBranch(brainDir, resolvedBranch); note != "" {
311						fmt.Fprintln(out, note)
312					}
313				}
314				hints := retrievalHintsForResults(repoDir, results, query)
315				for _, file := range hints.LikelyEditFiles {
316					fmt.Fprintf(out, "edit_file %s\n", file)
317				}
318				for _, file := range hints.LikelyTestFiles {
319					fmt.Fprintf(out, "test_file %s\n", file)
320				}
321				for _, action := range hints.ActionChecklist {
322					fmt.Fprintf(out, "action %s %s: %s\n", action.File, action.Symbol, action.Action)
323				}
324				for _, result := range results {
325					ex := base.TruncateString(strings.Join(strings.Fields(result.Text), " "), 200)
326					label := result.Source
327					if result.VerificationRequired {
328						label += " verify"
329					}
330					fmt.Fprintf(out, "[%s] %s  %s\n    %s\n", label, result.ID, unifiedResultLocation(result), ex)
331					printRetrievalCaveats(out, result)
332				}
333				for _, pattern := range related {
334					fmt.Fprintf(out, "related [%s] %s  %s\n", pattern.Type, pattern.ID, pattern.Title)
335				}
336				for _, preview := range abstractPreviews {
337					text := ""
338					if preview.Overview != nil {
339						text = "  " + strings.Join(strings.Fields(preview.Overview.Text), " ")
340					}
341					fmt.Fprintf(out, "abstract [%s] %s%s\n", preview.AbstractStatus, preview.SessionRef, text)
342					if preview.AbstractIssue != "" {
343						fmt.Fprintf(out, "  automatic enqueue issue: %s\n", preview.AbstractIssue)
344					}
345				}
346				if abstractPreviewsTruncated {
347					fmt.Fprintln(out, "abstract previews truncated")
348				}
349			}); err != nil {
350				return err
351			}
352			if err := writeRetrievalResponseBytes(cmd.OutOrStdout(), rendered.Bytes(), privacyPolicy); err != nil {
353				return err
354			}
355			if len(factIDs) > 0 {
356				recordReceipt()
357			}
358			return nil
359		}
360		// Ranking may be slow enough for a concurrent exclusion to land after its
361		// first guard snapshot. Revalidate immediately before transport assembly;
362		// no JSON or text bytes are emitted before this check succeeds.
363		results, policyAfter, err := revalidateRetrievalResponsePrivacy(brainDir, results)
364		if err != nil {
365			return err
366		}
367		if policyAfter != policyIdentityBeforeExtras {
368			// Optional derived material was read under a superseded privacy policy.
369			// Rows were freshly revalidated above; discard the stale extras instead
370			// of allowing a completed fast cleanup to make them look current.
371			related = nil
372			abstractPreviews = nil
373			abstractPreviewsTruncated = true
374		}
375		extras := retrievalTransportExtras{
376			AbstractPreviews:          abstractPreviews,
377			AbstractPreviewsTruncated: abstractPreviewsTruncated,
378			Hints:                     retrievalHintsForResults(repoDir, results, query),
379			Related:                   related,
380		}
381		if len(results) == 0 {
382			extras.BlindSpot = emptyResultBlindSpotOnBranch(brainDir, resolvedBranch)
383		}
384		if jsonOut {
385			// Preserve the established JSON `text` field
386			// surfaces. Excerpt is additive; existing consumers must not be forced to
387			// switch to a second brain_get round trip.
388			out, err := boundedRetrievalJSONPayload(query, resolvedBranch, results, extras)
389			if err != nil {
390				return err
391			}
392			serialized, err := jsonOutputBytes(out)
393			if err != nil {
394				return err
395			}
396			if err := writeRetrievalResponseBytes(cmd.OutOrStdout(), serialized, retrievalPrivacyPolicy{BrainDir: brainDir, Identity: policyAfter}); err != nil {
397				return err
398			}
399			if len(factIDs) > 0 {
400				recordReceipt()
401			}
402			return nil
403		}
404		text, err := boundedSingleRepoRetrievalText(query, results, extras)
405		if err != nil {
406			return err
407		}
408		if err := writeRetrievalResponseBytes(cmd.OutOrStdout(), text, retrievalPrivacyPolicy{BrainDir: brainDir, Identity: policyAfter}); err != nil {
409			return err
410		}
411		if len(factIDs) > 0 {
412			recordReceipt()
413		}
414		return nil
415	}
