417	func retrievalHintsForResults(repoRoot string, results []unifiedResult, query string) retrievalTaskHints {
418		_ = query
419		seen := map[string]struct{}{}
420		var editFiles, testFiles []string
421		addPath := func(path string) {
422			clean, ok := cleanBrainBriefHistoryFile(repoRoot, path)
423			if !ok || !brainBriefRepoFileExists(repoRoot, clean) {
424				return
425			}
426			if _, ok := seen[clean]; ok {
427				return
428			}
429			seen[clean] = struct{}{}
430			if brainBriefLikelyTestFile(clean) {
431				testFiles = append(testFiles, clean)
432			} else {
433				editFiles = append(editFiles, clean)
434			}
435		}
436		for _, result := range results {
437			if result.Source != "history" && result.Source != "doc" {
438				continue
439			}
440			addPath(result.Path)
441			for _, path := range extractBrainBriefPaths(result.Text) {
442				addPath(path)
443			}
444		}
445	
446		// Pair an indexed test locator with its conventional implementation path.
447		// This uses only the paths contained in indexed results plus bounded stat
448		// calls; ordinary retrieval never scans or reads the live source tree.
449		var siblingImplementations []string
450		for _, testFile := range testFiles {
451			for _, candidate := range retrievalSiblingImplementationCandidates(testFile) {
452				if _, exists := seen[candidate]; exists || !brainBriefRepoFileExists(repoRoot, candidate) {
453					continue
454				}
455				seen[candidate] = struct{}{}
456				siblingImplementations = append(siblingImplementations, candidate)
457			}
458		}
459		editFiles = append(siblingImplementations, editFiles...)
460		if len(editFiles) > 3 {
461			editFiles = editFiles[:3]
462		}
463		if len(testFiles) > 3 {
464			testFiles = testFiles[:3]
465		}
466		return retrievalTaskHints{LikelyEditFiles: editFiles, LikelyTestFiles: testFiles}
467	}
