469	func retrievalSiblingImplementationCandidates(testFile string) []string {
470		ext := filepath.Ext(testFile)
471		switch {
472		case strings.HasSuffix(testFile, "_test.go"):
473			return []string{strings.TrimSuffix(testFile, "_test.go") + ".go"}
474		case strings.HasSuffix(testFile, "_test.py"):
475			return []string{strings.TrimSuffix(testFile, "_test.py") + ".py"}
476		case strings.Contains(testFile, ".test"+ext):
477			return []string{strings.Replace(testFile, ".test"+ext, ext, 1)}
478		case strings.Contains(testFile, ".spec"+ext):
479			return []string{strings.Replace(testFile, ".spec"+ext, ext, 1)}
480		default:
481			return nil
482		}
483	}
