485	func compactUnifiedResults(results []unifiedResult, query string) []compactUnifiedResult {
486		if results == nil {
487			return []compactUnifiedResult{}
488		}
489		out := make([]compactUnifiedResult, len(results))
490		for i, result := range results {
491			out[i] = compactUnifiedResult{
492				Source: result.Source, ID: result.ID, Path: result.Path, Heading: result.Heading, Line: result.Line,
493				Text: result.Text, Excerpt: distinctRetrievalExcerpt(result.Text, query), Score: result.Score,
494				VerificationRequired: result.VerificationRequired, Caveats: result.Caveats, RelatedIDs: result.RelatedIDs,
495				EndLine: result.EndLine, Branch: result.Branch, SessionID: result.SessionID,
496				Agent: result.Agent, CreatedAt: result.CreatedAt, UpdatedAt: result.UpdatedAt, Truncated: result.Truncated,
497				MatchedTerms: result.MatchedTerms, SessionRef: result.SessionRef,
498				Concepts: result.Concepts, ConceptMatches: result.ConceptMatches,
499				EvidenceIDs: result.EvidenceIDs, WorstRank: result.WorstRank, RankSum: result.RankSum,
500				Approximate: result.Approximate, ResponseTruncated: result.ResponseTruncated,
501			}
502		}
503		return out
504	}
