506	// retrievalResultExcerpt centers a compact result on the densest query-term
507	// window. Ranked retrieval is a locator surface; get/multi-get own full bodies.
508	// distinctRetrievalExcerpt returns the bounded excerpt only when it adds
509	// information over Text; an identical projection is omitted.
510	func distinctRetrievalExcerpt(text, query string) string {
511		excerpt := retrievalResultExcerpt(text, query, retrievalExcerptBytes)
512		if excerpt == strings.Join(strings.Fields(text), " ") {
513			return ""
514		}
515		return excerpt
516	}
517	
518	func retrievalResultExcerpt(value, query string, maxBytes int) string {
519		text := strings.Join(strings.Fields(value), " ")
520		if maxBytes <= 0 || text == "" {
521			return ""
522		}
523		if len(text) <= maxBytes {
524			return text
525		}
526		lower, originalOffsets := foldedTextOffsets(text)
527		terms := semstore.QueryTokens(query)
528		bestStart, bestScore := 0, -1
529		for _, anchor := range terms {
530			for searchAt := 0; searchAt < len(lower); {
531				rel := strings.Index(lower[searchAt:], anchor)
532				if rel < 0 {
533					break
534				}
535				at := searchAt + rel
536				originalAt := originalOffsets[min(at, len(originalOffsets)-1)]
537				start := max(0, originalAt-maxBytes/3)
538				end := min(len(text), start+maxBytes)
539				for start > 0 && !utf8.RuneStart(text[start]) {
540					start--
541				}
542				for end < len(text) && !utf8.RuneStart(text[end]) {
543					end++
544				}
545				window := strings.ToLower(text[start:end])
546				score := 0
547				for _, term := range terms {
548					if strings.Contains(window, term) {
549						score += len(term)
550					}
551				}
552				if score > bestScore {
553					bestStart, bestScore = start, score
554				}
555				searchAt = at + len(anchor)
556			}
557		}
558		start := bestStart
559		end := min(len(text), start+maxBytes)
560		for start > 0 && !utf8.RuneStart(text[start]) {
561			start--
562		}
563		for end < len(text) && !utf8.RuneStart(text[end]) {
564			end++
565		}
566		excerpt := strings.TrimSpace(text[start:end])
567		if start > 0 {
568			excerpt = "..." + excerpt
569		}
570		if end < len(text) {
571			excerpt += "..."
572		}
573		return excerpt
574	}
575	
576	// foldedTextOffsets returns a lowercase search string plus a byte-offset map
577	// back to the original UTF-8 text. Unicode case folding can change byte length
578	// (for example, K -> k), so offsets into strings.ToLower(text) must never be
579	// applied directly to text.
580	func foldedTextOffsets(text string) (string, []int) {
581		var folded strings.Builder
582		offsets := make([]int, 0, len(text)+1)
583		for originalAt, r := range text {
584			lowerRune := strings.ToLower(string(r))
585			folded.WriteString(lowerRune)
586			for range []byte(lowerRune) {
587				offsets = append(offsets, originalAt)
588			}
589		}
590		offsets = append(offsets, len(text))
591		return folded.String(), offsets
592	}
