671	// errRetrievalIDsMissing is the gate `get` and `multi-get` close when an id the
672	// caller named was not in the brain.
673	var errRetrievalIDsMissing = errors.New("requested ids were not found")
674	
675	// retrievalMissingFailure turns "part of what you asked for is not here" into an
676	// exit code, AFTER the results and the `not found:` lines have been written.
677	//
678	// `show`, the sibling verb, already exits 1 for the one id it takes, while
679	// `get` and `multi-get` exited 0 whether they found everything, something or
680	// nothing -- so nothing downstream could branch without parsing stdout.
681	//
682	// ANY missing id fails, including a partial hit. Every id in the argument list
683	// is a request the caller made, and `get` is the one-id case of `multi-get`, so
684	// a rule that forgave a partial miss would make the SAME id exit 0 when asked
685	// for alongside a hit and 1 when asked for alone. Nothing is withheld to say
686	// it: the found results and the per-id `not found:` lines (or the JSON
687	// `missing` array) are already out, so a caller that wants the partial answer
688	// still has it and can ignore the code.
689	//
690	// renderedCommandError because the ids were named on the way out; repeating
691	// them on stderr would say it twice.
692	func retrievalMissingFailure(missing []string) error {
693		if len(missing) == 0 {
694			return nil
695		}
696		return renderedCommandError{err: fmt.Errorf("%w: %s", errRetrievalIDsMissing, strings.Join(missing, ", "))}
697	}
