699	func outputWantsJSON(jsonOut bool, format string) (bool, error) {
700		switch strings.ToLower(strings.TrimSpace(format)) {
701		case "":
702			return jsonOut, nil
703		case "json":
704			return true, nil
705		case "cli":
706			return false, nil
707		default:
708			return false, fmt.Errorf("--format must be json or cli")
709		}
710	}
711	
712	// runGet emits the requested items and REPORTS which ids were not found rather
713	// than failing on them. The miss is a result, not an error: the JSON payload
714	// keeps carrying `missing`. Turning a miss into an exit code is the CLI's job,
715	// one layer up -- see retrievalMissingFailure.
716	func runGet(ctx context.Context, cmd *cobra.Command, opts Options, ids []string, branch string, jsonOut bool, gopts getOptions, surface string) ([]string, error) {
717		repoDir, brainDir, resolvedBranch, err := resolveFactsTarget(ctx, opts, agentSurfaceTarget(opts, nil), branch)
718		if err != nil {
719			return nil, err
720		}
721		privacyPolicy, err := brainstore.CaptureRetrievalPrivacyPolicy(brainDir)
722		if err != nil {
723			return nil, err
724		}
725		requestedPattern := false
726		for _, id := range ids {
727			if strings.HasPrefix(id, "pattern:") || strings.HasPrefix(id, "theme:") {
728				privacyPolicy.RequireDerivedClean = true
729				requestedPattern = true
730				break
731			}
732		}
733		if requestedPattern {
734			if err := requirePrivacyDerivedRead(brainDir); err != nil {
735				return nil, err
736			}
737			if err := requirePatternCorpusAvailable(brainDir); err != nil {
738				return nil, err
739			}
740		}
741		// An id that query or search just handed back and get reports missing is a
742		// worse seam than not returning it at all.
743		if globalFacts, globalErr := globalFactsForRead(opts.Env, false); globalErr != nil {
744			fmt.Fprintf(cmd.ErrOrStderr(), "warning: global memories unavailable: %v\n", globalErr)
745		} else {
746			gopts.GlobalFacts = globalFacts
747		}
748		found, missing, err := getUnifiedBatchOptions(repoDir, brainDir, resolvedBranch, ids, gopts)
749		if err != nil {
750			return nil, err
751		}
752		factIDs := unifiedFactIDs(found)
753		recordReceipt := func() {
754			recordServedFacts(cmd.ErrOrStderr(), vitalityNow(opts), brainDir, resolvedBranch, surface,
755				vitalityHead(ctx, opts.Runner, repoDir), "", factIDs)
756		}
757		// Normalize empty collections to [] so --json emits arrays, not null, matching
758		// the repo's JSON contract (see TestInspectCodeEmptyResultsEmitArrayNotNull).
759		if found == nil {
760			found = []unifiedResult{}
761		}
762		if missing == nil {
763			missing = []string{}
764		}
765		// Computed BEFORE the output split, because both surfaces need it.
766		//
767		// These notes lived only in the text block, so `get --json` never carried
768		// them. The agent surface, the one most likely to act on a "--branch" hint,
769		// was the one surface that could not see it. The integrity note had the
770		// same gap before this change and inherits the fix.
771		missNote := getMissNote(brainDir, resolvedBranch, missing)
772		if jsonOut {
773			payload := map[string]any{"branch": resolvedBranch, "results": found, "missing": missing}
774			if missNote != "" {
775				payload["blind_spot"] = missNote
776			}
777			serialized, err := jsonOutputBytes(payload)
778			if err != nil {
779				return nil, err
780			}
781			if err := writeRetrievalResponseBytes(cmd.OutOrStdout(), serialized, privacyPolicy); err != nil {
782				return nil, err
783			}
784			if len(factIDs) > 0 {
785				recordReceipt()
786			}
787			return missing, nil
788		}
789		var rendered bytes.Buffer
790		if err := cmdutil.WriteTextToWriter(&rendered, func(out io.Writer) {
791			for _, r := range found {
792				label := r.Source
793				if r.VerificationRequired {
794					label += " verify"
795				}
796				fmt.Fprintf(out, "[%s] %s  %s\n%s\n", label, r.ID, unifiedResultLocation(r), r.Text)
797				printRetrievalCaveats(out, r)
798				printConversationTurns(out, r)
799				fmt.Fprintln(out)
800			}
801			for _, id := range missing {
802				fmt.Fprintf(out, "not found: %s\n", id)
803			}
804			// "not found" for an id the caller is already holding makes the same
805			// claim the empty-result note makes: that the item was never there.
806			// When the fact store cannot produce what the manifest declares, that
807			// claim is wrong — and `get fact:<id>` is usually the exact moment a
808			// user discovers the loss.
809			if missNote != "" {
810				fmt.Fprintf(out, "%s\n", missNote)
811			}
812		}); err != nil {
813			return nil, err
814		}
815		if err := writeRetrievalResponseBytes(cmd.OutOrStdout(), rendered.Bytes(), privacyPolicy); err != nil {
816			return nil, err
817		}
818		if len(factIDs) > 0 {
819			recordReceipt()
820		}
821		return missing, nil
822	}
