824	// unifiedResultLocation renders a result's source anchor, including the
825	// inclusive end line for range-bearing results (conversation exchanges).
826	func unifiedResultLocation(r unifiedResult) string {
827		switch {
828		case r.Line > 0 && r.EndLine > r.Line:
829			return fmt.Sprintf("%s:%d-%d", r.Path, r.Line, r.EndLine)
830		case r.Line > 0:
831			return fmt.Sprintf("%s:%d", r.Path, r.Line)
832		default:
833			return r.Path
834		}
835	}
