837	func printRetrievalCaveats(out io.Writer, result unifiedResult) {
838		for _, caveat := range result.Caveats {
839			fmt.Fprintf(out, "    verify: %s\n", caveat.Message)
840			details := make([]string, 0, 4)
841			if len(caveat.Paths) > 0 {
842				details = append(details, "paths="+strings.Join(caveat.Paths, ","))
843			}
844			if caveat.ReviewID != "" {
845				details = append(details, "review="+caveat.ReviewID)
846			}
847			if caveat.Action != "" {
848				details = append(details, "action="+caveat.Action)
849				details = append(details, fmt.Sprintf("confidence=%.2f", caveat.Confidence))
850			}
851			if len(details) > 0 {
852				fmt.Fprintf(out, "      details: %s\n", strings.Join(details, "  "))
853			}
854		}
855	}
