873	func (s querySelection) mode(fallback retrievalMode) (retrievalMode, error) {
874		if s.keyword && s.semantic {
875			return fallback, fmt.Errorf("--keyword and --semantic are mutually exclusive")
876		}
877		if s.keyword {
878			return retrieval.ModeLexical, nil
879		}
880		if s.semantic {
881			// Semantic retrieval was removed (trail #278); the flag is honored as
882			// a compatibility alias for the default BM25 ranking.
883			return retrieval.ModeHybrid, nil
884		}
885		return fallback, nil
886	}
