91	// lexical scorer so docs don't vanish when the doc FTS index can't open.
92	func rankDocsForRetrieval(brainDir string, index docIndex, query string, limit int) []scoredDocRecord {
93		scored, ok := rankDocsViaFTS(brainDir, index, query, limit)
94		if !ok {
95			scored = rankDocsLexical(index, query, limit)
96		}
97		return scored
98	}
99	
100	// errConversationVectorUnsupported answers a direct modeVector call on the
101	// conversation source. No surface produces modeVector anymore (the
102	// verbs alias to the lexical ranking); this guards internal callers.
103	var errConversationVectorUnsupported = errors.New(`vector search was removed with semantic retrieval (trail #278); use query --source conversation for lexical recall`)
104	
105	// conversationSessionTopKDivisor sets the default per-session share of a
106	// conversation result list: one session may hold at most limit/2 (min 1) of
107	// the returned results while other sessions still have candidates. Dogfooding
108	// measured single sessions holding 29–84% of a brain's exchanges; without a
109	// cap one long session crowds out every other trajectory.
110	const conversationSessionTopKDivisor = 2
111	
112	// retrieveConversation is the explicit conversation-source arm over exchange
113	// records only, then structured filters and a per-session diversity cap. It
114	// never consults facts, docs, or classified history, and every result carries
115	// the historical-evidence contract. Ranking by mode: search is BM25 (substring
116	// scorer as fallback); query fuses BM25 with calibrated conversation vectors
117	// when the gated semantic arm is available and degrades to exactly the lexical
118	// ranking otherwise; vsearch is semantic-only and returns a structured
119	// unavailable error when the arm is closed.
120	func retrieveConversation(brainDir, query string, limit int, mode retrievalMode, opts retrievalOptions) ([]unifiedResult, error) {
121		manifest, err := bmanifest.Load(brainDir)
122		if err != nil {
123			return nil, err
124		}
125		if manifest.Sources == nil || manifest.Sources.History == nil {
126			if mode == retrieval.ModeVector {
127				return nil, errConversationVectorUnsupported
128			}
129			return nil, nil
130		}
131		fresh, err := loadFreshHistory(brainDir, manifest.Sources.History)
132		if err != nil {
133			return nil, fmt.Errorf("load history index: %w", err)
134		}
135		filtered := opts.HasConversationOnlyFilters() || strings.TrimSpace(opts.Branch) != ""
136		// Structured filters are pushed into candidate generation: every
137		// arm ranks only in-scope records, so a valid session/agent/time/branch
138		// match can never be displaced out of a bounded candidate window by
139		// higher-ranked out-of-scope rows. The over-fetch below is dedup/diversity
140		// headroom only. The exclusion guard joins the same predicate: a
141		// tombstoned session is unreadable here even while its derived cleanup is
142		// still running. Superseded duplicate copies join it too: a stale
143		// copy must not even consume a candidate slot.
144		guard, err := bmanifest.LoadSessionReadGuard(brainDir, manifest)
145		if err != nil {
146			return nil, err
147		}
148		winners := fresh.duplicateRecordWinners()
149		var pred func(historyRecord) bool
150		if filtered || !guard.Empty() || len(winners) > 0 {
151			pred = func(r historyRecord) bool {
152				if historystore.GuardBlocksRecord(guard, r) {
153					return false
154				}
155				if w, ok := winners[recordReplacementKey(r)]; ok && !sameRecordCopy(w, r) {
156					return false
157				}
158				return !filtered || conversationRecordMatchesFilters(r, opts)
159			}
160		}
161		candidateLimit := limit * 4
162		if candidateLimit < limit { // overflow guard
163			candidateLimit = limit
164		}
165		scanComplete := true
166		var scored []scoredHistoryRecord
167		switch mode {
168		case retrieval.ModeVector:
169			return nil, errConversationVectorUnsupported
170		case retrieval.ModeHybrid:
171			scored = rankFreshHistory(fresh, conversationKind, query, candidateLimit, pred, func(longTerm historyIndex, eligible func(historyRecord) bool) ([]scoredHistoryRecord, bool) {
172				lex, complete, ok := rankHistoryViaFTSFiltered(brainDir, longTerm, conversationKind, query, candidateLimit, historyFTSRelevanceCutoff, eligible)
173				if ok && !complete {
174					scanComplete = false
175				}
176				return lex, ok
177			})
178		default:
179			scored = rankFreshHistory(fresh, conversationKind, query, candidateLimit, pred, func(longTerm historyIndex, eligible func(historyRecord) bool) ([]scoredHistoryRecord, bool) {
180				lex, complete, ok := rankHistoryViaFTSFiltered(brainDir, longTerm, conversationKind, query, candidateLimit, historyFTSRelevanceCutoff, eligible)
181				if ok && !complete {
182					scanComplete = false
183				}
184				return lex, ok
185			})
186		}
187		// complete is only meaningful when the arm actually ran. On ok == false the
188		// FTS/fused arm was UNAVAILABLE (no match expression, open/query failure),
189		// and rankFreshHistory falls back to the in-memory scorer, which filters
190		// the complete long-term record slice and therefore cannot be partial.
191		// Honoring a stale complete=false there turned every FTS outage into a
192		// bogus "filter scan exceeded" error on the default (unfiltered) path,
193		// contradicting this file's own contract that FTS is an optimization and
194		// never load-bearing.
195		if !scanComplete {
196			return nil, errConversationFilterScanExceeded()
197		}
198		// Defense in depth: every arm already generated in-scope candidates; this
199		// re-check keeps the contract obvious and cheap.
200		kept := make([]scoredHistoryRecord, 0, len(scored))
201		for _, s := range scored {
202			if historystore.GuardBlocksRecord(guard, s.Record) {
203				continue
204			}
205			if conversationRecordMatchesFilters(s.Record, opts) {
206				kept = append(kept, s)
207			}
208		}
209		kept = capConversationSessionShare(kept, limit, opts)
210		if len(kept) > limit {
211			kept = kept[:limit]
212		}
213		out := make([]unifiedResult, len(kept))
214		for i, s := range kept {
215			out[i] = conversationToUnified(s.Record)
216			// Session navigation identity: every hit names its virtual
217			// session so callers can fetch the outline or adjacent context.
218			out[i].SessionRef, _ = recordSessionRef(s.Record, manifest.RepoKey, manifest)
219			// Explainability: which query tokens actually hit this record, so a
220			// thin result is debuggable ("only 'bug' matched") instead of opaque.
221			out[i].MatchedTerms = historyRecordMatchedTerms(s.Record, query)
222			// Preserve list order for callers that read Score; RRF-scale for
223			// consistency with single-list merges.
224			out[i].Score = 1.0 / (retrieval.RRFK + float64(i+1))
225		}
226		return out, nil
227	}
228	
229	// maxGetBatchIDs caps one get/multi-get request across CLI and
230	// workspace surfaces (the plan's shared result-limit ceiling).
231	const maxGetBatchIDs = 50
232	
233	// errConversationFilterScanExceeded is the structured degraded state for a
234	// filtered conversation scan that hit its candidate ceiling before filling the
235	// requested limit: completeness cannot be proven, so the caller gets an
236	// explicit error rather than a silently partial (possibly false-empty) result.
237	func errConversationFilterScanExceeded() error {
238		return fmt.Errorf("conversation filter scan exceeded %d candidates before the requested limit was met; results would be incomplete, narrow the query or the filters", historyFTSFilteredScanCeiling)
239	}
240	
241	// conversationRecordMatchesFilters applies the structured conversation filters.
242	// Scope safety over recall: a record that cannot prove it is inside a time
243	// filter (no session time) is excluded when one is set.
244	func conversationRecordMatchesFilters(record historyRecord, opts retrievalOptions) bool {
245		if session := strings.TrimSpace(opts.SessionID); session != "" && record.SessionID != session {
246			return false
247		}
248		if agent := strings.TrimSpace(opts.Agent); agent != "" && !strings.EqualFold(record.Agent, agent) {
249			return false
250		}
251		if branch := strings.TrimSpace(opts.Branch); branch != "" && record.Branch != branch {
252			return false
253		}
254		if !opts.After.IsZero() || !opts.Before.IsZero() {
255			created, err := time.Parse(time.RFC3339, record.CreatedAt)
256			if err != nil {
257				return false
258			}
259			if !opts.After.IsZero() && created.Before(opts.After) {
260				return false
261			}
262			if !opts.Before.IsZero() && !created.Before(opts.Before) {
263				return false
264			}
265		}
266		return true
267	}
268	
269	// capConversationSessionShare enforces the per-session diversity cap: at most
270	// max(1, limit/conversationSessionTopKDivisor) results per session while other
271	// sessions still have candidates. If the cap leaves the list short and only
272	// capped sessions have candidates left, they backfill in rank order; the cap
273	// prevents crowding out, it does not hide the only matching session. An
274	// explicit session filter disables the cap entirely.
275	func capConversationSessionShare(scored []scoredHistoryRecord, limit int, opts retrievalOptions) []scoredHistoryRecord {
276		if strings.TrimSpace(opts.SessionID) != "" || len(scored) <= 1 {
277			return scored
278		}
279		perSession := limit / conversationSessionTopKDivisor
280		if perSession < 1 {
281			perSession = 1
282		}
283		counts := map[string]int{}
284		kept := make([]scoredHistoryRecord, 0, min(limit, len(scored)))
285		var overflow []scoredHistoryRecord
286		for _, s := range scored {
287			key := s.Record.SessionID
288			if key == "" {
289				key = s.Record.Path
290			}
291			if counts[key] >= perSession {
292				overflow = append(overflow, s)
293				continue
294			}
295			counts[key]++
296			kept = append(kept, s)
297			if len(kept) >= limit {
298				return kept
299			}
300		}
301		for _, s := range overflow {
302			if len(kept) >= limit {
303				break
304			}
305			kept = append(kept, s)
306		}
307		return kept
308	}
309	
310	// conversationToUnified projects an exchange record for search results: the
311	// bounded search projection plus provenance and the historical-evidence
312	// contract. Full bounded content is get's job.
313	func conversationToUnified(record historyRecord) unifiedResult {
314		return unifiedResult{
315			Source:               brainstore.RetrievalSourceConversation,
316			ID:                   record.ID,
317			Path:                 record.Path,
318			Heading:              conversationKind,
319			Line:                 record.Line,
320			EndLine:              record.EndLine,
321			Branch:               record.Branch,
322			SessionID:            record.SessionID,
323			Agent:                record.Agent,
324			CreatedAt:            record.CreatedAt,
325			Text:                 record.Summary,
326			Truncated:            record.ProjectionTruncated,
327			VerificationRequired: true,
328			Caveats:              []retrievalCaveat{conversationHistoricalEvidenceCaveat()},
329		}
330	}
331	
332	// conversationGetResult is the bounded ID-based expansion: re-parse the exact
333	// indexed range from the canonical transcript when its digest still matches;
334	// otherwise degrade to the stored projection with a caveat naming WHICH
335	// contract failed. Too-large, stale, and unreadable sources are distinct
336	// states, never one collapsed "stale" answer.
337	func conversationGetResult(brainDir string, record historyRecord) unifiedResult {
338		result := conversationToUnified(record)
339		expansion, err := expandConversationExchange(brainDir, record)
340		switch {
341		case err == nil:
342			result.Text = conversationExpansionText(expansion)
343			result.Truncated = expansion.Truncated
344		case errors.Is(err, errConversationSourceTooLarge):
345			result.Caveats = append(result.Caveats, conversationSourceTooLargeCaveat(record.Path))
346		case errors.Is(err, errConversationSourceStale):
347			result.Caveats = append(result.Caveats, conversationSourceStaleCaveat(record.Path))
348		default:
349			result.Caveats = append(result.Caveats, conversationSourceUnreadableCaveat(record.Path))
350		}
351		return result
352	}
353	
354	// getUnifiedBatch resolves prefixed ids (fact:/review:/history:/doc:/pattern:/theme:) to full records,
355	// loading each corpus at most once and indexing it by id. get/multi-get
356	// route through here so resolving N ids is O(corpus
357	// + N), not O(N × corpus) — the latter rescans the full history per id and is
358	// pathological on large brains. Results preserve input order.
359	func getUnifiedBatch(repoDir, brainDir, branch string, ids []string) (found []unifiedResult, missing []string, err error) {
360		return getUnifiedBatchOptions(repoDir, brainDir, branch, ids, getOptions{})
361	}
362	
363	func getUnifiedBatchOptions(repoDir, brainDir, branch string, ids []string, gopts getOptions) (found []unifiedResult, missing []string, err error) {
364		// One request fans out to at most this many record resolutions; each
365		// conversation id triggers a bounded transcript read, so the batch size
366		// itself must be bounded too.
367		if len(ids) > maxGetBatchIDs {
368			return nil, nil, fmt.Errorf("at most %d ids per get/multi-get request (got %d)", maxGetBatchIDs, len(ids))
369		}
370		if err := validateGetOptions(gopts); err != nil {
371			return nil, nil, err
372		}
373		var wantFact, wantReview, wantHistory, wantConversation, wantSession, wantDoc, wantPatternDerived bool
374		for _, id := range ids {
375			switch {
376			case strings.HasPrefix(id, "fact:"):
377				wantFact = true
378			case strings.HasPrefix(id, "review:"):
379				wantReview = true
380			case strings.HasPrefix(id, "history:"):
381				wantHistory = true
382			case strings.HasPrefix(id, brainstore.ConversationSessionIDPrefix):
383				wantSession = true
384			case strings.HasPrefix(id, conversationIDPrefix):
385				wantConversation = true
386			case strings.HasPrefix(id, "doc:"):
387				wantDoc = true
388			case strings.HasPrefix(id, "pattern:"), strings.HasPrefix(id, "theme:"):
389				wantPatternDerived = true
390			}
391		}
392		if wantPatternDerived {
393			if err := requirePrivacyDerivedRead(brainDir); err != nil {
394				return nil, nil, err
395			}
396		}
397		// Navigation arguments are type-specific: context counts belong to a
398		// single conversation: target, outline cursor/limit to a single
399		// conversation-session: target. Anything else is a structured
400		// invalid-argument error, never an ignored option.
401		if gopts.navigation() && len(ids) != 1 {
402			return nil, nil, fmt.Errorf("navigation options require exactly one target id (got %d)", len(ids))
403		}
404		if gopts.ContextSet && !wantConversation {
405			return nil, nil, fmt.Errorf("context-before/context-after are valid only for a conversation: target")
406		}
407		if gopts.OutlineSet && !wantSession {
408			return nil, nil, fmt.Errorf("after-turn/limit are valid only for a conversation-session: target")
409		}
410		if wantSession && len(ids) != 1 {
411			return nil, nil, fmt.Errorf("a conversation-session: outline requires its own single-id request")
412		}
413		// Exclusion guard: a tombstoned session's records resolve as "not
414		// found" on every get surface immediately, even before cleanup finishes.
415		guard, err := bmanifest.LoadSessionReadGuard(brainDir, nil)
416		if err != nil {
417			return nil, nil, err
418		}
419		if !guard.Empty() {
420			// Resolve the manifest-derived transcript paths BEFORE the facts arm
421			// filters below, so a fact whose only anchor lost its session id blocks
422			// by path here too. The history arm's later re-resolution ran after
423			// factstore.GuardRecords and therefore never protected `get fact:`.
424			manifest, err := bmanifest.Load(brainDir)
425			if err != nil {
426				return nil, nil, err
427			}
428			guard, err = bmanifest.LoadSessionReadGuard(brainDir, manifest)
429			if err != nil {
430				return nil, nil, err
431			}
432		}
433		factByID := map[string]factRecord{}
434		var globalGetIDs map[string]bool
435		var reviewByID map[string]factReviewGroup
436		var reviewByFactID map[string]factReviewGroup
437		var proposalStateUnavailable bool
438		if wantFact || wantReview {
439			// Surface a corrupt facts store as an error, not a misleading "not found".
440			facts, ferr := factstore.Load(brainDir, branch)
441			if ferr != nil {
442				return nil, nil, ferr
443			}
444			if len(gopts.GlobalFacts) > 0 {
445				// query and search return global facts, so their ids have to
446				// resolve here too. The repository's copy still wins on a collision.
447				facts, globalGetIDs = retrieval.MergeGlobalFacts(facts, gopts.GlobalFacts)
448			}
449			facts = factstore.GuardRecords(guard, facts)
450			for _, f := range facts {
451				factByID[f.ID] = f
452			}
453			proposals, perr := loadFactProposals(brainDir, branch)
454			if perr != nil && wantReview {
455				return nil, nil, perr
456			}
457			if perr == nil {
458				localFacts := retrieval.FactsEligibleForLocusDrift(facts, globalGetIDs)
459				reviewByID, reviewByFactID = retrieval.IndexFactReviewGroups(retrieval.BuildFactReviewGroups(localFacts, proposals))
460			} else {
461				proposalStateUnavailable = true
462			}
463		}
464		histByID := map[string]historyRecord{}
465		convByID := map[string]historyRecord{}
466		var sessionViews map[string]conversationSessionView
467		var abstractResolver *sessionAbstractResolver
468		// convScopes maps a conversation id to its session scopes (ref -> newest
469		// record in that scope), so a legacy id colliding across scopes is a
470		// structured ambiguity, never a silent last-write-wins pick.
471		convScopes := map[string]map[string]historyRecord{}
472		if wantHistory || wantConversation || wantSession {
473			// A corrupt manifest, or a history index the manifest declares but that is
474			// missing/unreadable, is a real storage problem — surface it rather than
475			// reporting every history:* id as "not found". A brain with no history source
476			// (nil) legitimately has no such records, so leave histByID empty.
477			manifest, err := bmanifest.Load(brainDir)
478			if err != nil {
479				return nil, nil, err
480			}
481			if manifest.Sources != nil && manifest.Sources.History != nil {
482				fresh, err := loadFreshHistory(brainDir, manifest.Sources.History)
483				if err != nil {
484					return nil, nil, fmt.Errorf("load history index: %w", err)
485				}
486				// The guard already carries the manifest-derived transcript paths
487				// (resolved above, before the facts arm), so records that lost
488				// their session id block by path on every surface here.
489				if wantConversation || wantSession {
490					sessionViews = buildConversationSessionViews(fresh, manifest.RepoKey, manifest, guard)
491					for ref, view := range sessionViews {
492						for _, r := range view.Records {
493							scopes := convScopes[r.ID]
494							if scopes == nil {
495								scopes = map[string]historyRecord{}
496								convScopes[r.ID] = scopes
497							}
498							if prev, ok := scopes[ref]; ok {
499								scopes[ref] = newestHistoryRecord(prev, r)
500							} else {
501								scopes[ref] = r
502							}
503						}
504					}
505				}
506				// reconciledRecords collapses duplicate stable IDs to the same
507				// newest-copy winner ranking uses, so get expands exactly the
508				// record search returned.
509				for _, r := range fresh.reconciledRecords() {
510					if historystore.GuardBlocksRecord(guard, r) {
511						continue
512					}
513					if r.Kind == conversationKind {
514						convByID[r.ID] = r
515						continue
516					}
517					histByID[r.ID] = r
518				}
519			}
520		}
521		if wantSession {
522			abstractResolver = newSessionAbstractResolver(brainDir)
523		}
524		docByID := map[string]docRecord{}
525		if wantDoc {
526			// A never-built doc index is not an error (doc:* ids just report "not
527			// found"); a corrupt/unreadable one is — surface it.
528			index, err := docstore.Load(brainDir)
529			switch {
530			case err == nil:
531				for _, r := range index.Records {
532					docByID[r.ID] = r
533				}
534			case os.IsNotExist(err):
535				if defect := inspectBrainDeclaredIndex(brainDir, brainstore.DeclaredIndexDocs); !defect.OK() {
536					return nil, nil, defect
537				}
538			case !os.IsNotExist(err):
539				return nil, nil, fmt.Errorf("load doc index: %w", err)
540			}
541		}
542		for _, id := range ids {
543			switch {
544			case strings.HasPrefix(id, "fact:"):
545				if f, ok := factByID[id]; ok {
546					r := retrieval.FactsToUnified([]factRecord{f})[0]
547					if group, pending := reviewByFactID[id]; pending {
548						r = retrieval.AnnotateExplicitFactReview(r, group)
549					}
550					if globalGetIDs[f.ID] {
551						// Not scoped to this repository, so locus drift cannot
552						// answer for it; labelled the way the ranked surfaces are.
553						r.Heading += " (global)"
554					} else {
555						r = retrieval.AnnotateFactLocusTrust(repoDir, f, r)
556					}
557					if proposalStateUnavailable {
558						r = retrieval.AnnotateProposalStateUnavailable([]unifiedResult{r})[0]
559					}
560					found = append(found, r)
561					continue
562				}
563			case strings.HasPrefix(id, "review:"):
564				if group, ok := reviewByID[id]; ok {
565					r := retrieval.FactReviewToUnified(repoDir, group)
566					// Preserve an addressable proposal alias if the group grew, including
567					// the machine-readable caveat that tells clients what to review.
568					r.ID = id
569					for i := range r.Caveats {
570						if r.Caveats[i].Kind == retrieval.CaveatUnresolvedReview {
571							r.Caveats[i].ReviewID = id
572						}
573					}
574					found = append(found, r)
575					continue
576				}
577			case strings.HasPrefix(id, "history:"):
578				if r, ok := histByID[id]; ok {
579					found = append(found, retrieval.HistoryToUnified([]scoredHistoryRecord{{Record: r}})[0])
580					continue
581				}
582			case strings.HasPrefix(id, brainstore.ConversationSessionIDPrefix):
583				if view, ok := sessionViews[id]; ok {
584					outline := conversationSessionOutline(view, gopts.AfterTurn, gopts.OutlineLimit)
585					outline.AbstractStatus, outline.Abstract = abstractResolver.status(view)
586					outline = boundSessionAbstractEnvelope(outline)
587					if outline.AbstractStatus == abstractStatusStale || outline.AbstractStatus == abstractStatusMissing {
588						if err := enqueueAutomaticAbstractReconciliationHook(brainDir, "session_get", time.Now().UTC()); err != nil {
589							// Automatic generation is an optional acceleration. Exact
590							// session recall remains valid even when its durable work
591							// enqueue is temporarily unavailable; expose the issue instead
592							// of converting a successful get into a failure.
593							outline.AbstractIssue = memoryOperationalError(err)
594						}
595					}
596					found = append(found, outline)
597					continue
598				}
599			case strings.HasPrefix(id, conversationIDPrefix):
600				// The transcript path is resolved from the indexed record only;
601				// a client-supplied id can never choose a filesystem path.
602				scopes := convScopes[id]
603				if len(scopes) > 1 {
604					// The existing branch selector may disambiguate a legacy id
605					// that collides across session scopes; a silent winner never
606					// may.
607					matching := map[string]historyRecord{}
608					for ref, record := range scopes {
609						if record.Branch == branch {
610							matching[ref] = record
611						}
612					}
613					if len(matching) != 1 {
614						return nil, nil, fmt.Errorf("memory_identity_ambiguous: %s resolves to %d session scopes; pass --branch to select one", id, len(scopes))
615					}
616					scopes = matching
617				}
618				if len(scopes) == 1 {
619					for ref, record := range scopes {
620						if gopts.ContextSet {
621							found = append(found, conversationContextPacket(brainDir, sessionViews[ref], record, gopts.ContextBefore, gopts.ContextAfter))
622						} else {
623							result := conversationGetResult(brainDir, record)
624							result.SessionRef = ref
625							found = append(found, result)
626						}
627					}
628					continue
629				}
630				if r, ok := convByID[id]; ok {
631					found = append(found, conversationGetResult(brainDir, r))
632					continue
633				}
634			case strings.HasPrefix(id, "doc:"):
635				if r, ok := docByID[strings.TrimPrefix(id, "doc:")]; ok {
636					found = append(found, retrieval.DocToUnified(r))
637					continue
638				}
639			case strings.HasPrefix(id, "pattern:"):
640				// Consolidation dossier addressed by its pattern id (v2). Corpus is
641				// rebuildable/optional, so a missing corpus is "not found", not an error.
642				if r, ok, err := getCorpusConsolidationChecked(brainDir, id); err != nil {
643					return nil, nil, err
644				} else if ok {
645					found = append(found, r)
646					continue
647				}
648			case strings.HasPrefix(id, "theme:"):
649				if r, ok, err := getCorpusThemeChecked(brainDir, id); err != nil {
650					return nil, nil, err
651				} else if ok {
652					found = append(found, r)
653					continue
654				}
655			}
656			missing = append(missing, id)
657		}
658		return found, missing, nil
659	}
