17	// retrievalTransportExtras is the already-bounded, optional material carried
18	// beside ranked rows. The final response budget is still measured against the
19	// complete serialized shape: these fields, query/branch, indentation, and an
20	// envelope all count.
21	type retrievalTransportExtras struct {
22		AbstractPreviews          []sessionAbstractPreview
23		AbstractPreviewsTruncated bool
24		Hints                     retrievalTaskHints
25		Related                   []relatedPatternRef
26		BlindSpot                 string
27	}
