101	// withLockedRetrievalPrivacyPolicies is the response linearization boundary
102	// (brainstore owns the lock ordering and identity revalidation); the CLI
103	// adapters bind the derived-read gate.
104	func withLockedRetrievalPrivacyPolicies(policies []retrievalPrivacyPolicy, fn func() error) error {
105		return brainstore.WithLockedRetrievalPrivacyPolicies(policies, requirePrivacyDerivedRead, fn)
106	}
107	
108	func acquireRetrievalPrivacyPolicies(policies []retrievalPrivacyPolicy) (func(), error) {
109		return brainstore.AcquireRetrievalPrivacyPolicies(policies, requirePrivacyDerivedRead)
110	}
111	
112	// commitVizRetrievalResponse is the viz HTTP transport's final privacy
113	// boundary: it binds the cli race seams and the locked-policy write around the
114	// buffered response commit (injected as viz.Deps.CommitRetrievalResponse).
115	func commitVizRetrievalResponse(policies []retrievalPrivacyPolicy, write func() error) error {
116		beforeRetrievalResponsePrivacyEmissionCheck()
117		return withLockedRetrievalPrivacyPolicies(policies, func() error {
118			beforeRetrievalResponseWrite()
119			return write()
120		})
121	}
