123	// revalidateRetrievalResponsePrivacy closes the ranking-to-write window. A
124	// tombstone that appears after ranking either makes the authoritative derived
125	// state dirty (and fails the response closed) or is fully cleaned and reaches
126	// the freshly loaded session guard below.
127	func revalidateRetrievalResponsePrivacy(brainDir string, results []unifiedResult) ([]unifiedResult, string, error) {
128		beforeRetrievalResponsePrivacyRecheck()
129		allowed, err := privacyDerivedReadGate(brainDir)
130		if err != nil {
131			return nil, "", err
132		}
133		if !allowed {
134			return nil, "", fmt.Errorf("%s: retrieval state changed after ranking; retry after excluded-session cleanup verifies clean", brainstore.PrivacyDirtyCode)
135		}
136		manifest, err := bmanifest.Load(brainDir)
137		if err != nil {
138			return nil, "", err
139		}
140		guard, err := bmanifest.LoadSessionReadGuard(brainDir, manifest)
141		if err != nil {
142			return nil, "", err
143		}
144		if len(results) == 0 {
145			return results, guard.PolicyIdentity, nil
146		}
147		if guard.Empty() {
148			return results, guard.PolicyIdentity, nil
149		}
150	
151		// A completed exclusion deliberately retains canonical transcripts, so a
152		// clean derived-state verification alone is insufficient. Rebuild the
153		// allowed virtual-session set through the fresh guard and drop any response
154		// row whose direct or nested conversation proof is no longer readable.
155		allowedRefs := map[string]bool{}
156		allowedEvidence := map[string]bool{}
157		if manifest.Sources != nil && manifest.Sources.History != nil {
158			fresh, loadErr := loadFreshHistory(brainDir, manifest.Sources.History)
159			if loadErr != nil {
160				return nil, "", fmt.Errorf("load history for privacy recheck: %w", loadErr)
161			}
162			for ref, view := range buildConversationSessionViews(fresh, manifest.RepoKey, manifest, guard) {
163				allowedRefs[ref] = true
164				for _, record := range view.Records {
165					allowedEvidence[record.ID] = true
166				}
167			}
168		}
169		kept := make([]unifiedResult, 0, len(results))
170		for _, result := range results {
171			if guard.BlocksSession(result.SessionID) || historystore.GuardBlocksRecord(guard, historyRecord{Path: result.Path}) {
172				continue
173			}
174			if result.SessionRef != "" && !allowedRefs[result.SessionRef] {
175				continue
176			}
177			blockedProof := false
178			for _, id := range result.EvidenceIDs {
179				if strings.HasPrefix(id, conversationIDPrefix) && !allowedEvidence[id] {
180					blockedProof = true
181					break
182				}
183			}
184			if !blockedProof {
185				for _, match := range result.ConceptMatches {
186					if strings.HasPrefix(match.ConversationID, conversationIDPrefix) && !allowedEvidence[match.ConversationID] {
187						blockedProof = true
188						break
189					}
190				}
191			}
192			if !blockedProof {
193				kept = append(kept, result)
194			}
195		}
196		return kept, guard.PolicyIdentity, nil
197	}
