259	func cloneRetrievalTransportExtras(extras retrievalTransportExtras) retrievalTransportExtras {
260		extras.AbstractPreviews = append([]sessionAbstractPreview(nil), extras.AbstractPreviews...)
261		extras.Hints.LikelyEditFiles = append([]string(nil), extras.Hints.LikelyEditFiles...)
262		extras.Hints.LikelyTestFiles = append([]string(nil), extras.Hints.LikelyTestFiles...)
263		extras.Hints.ActionChecklist = append([]brainBriefAction(nil), extras.Hints.ActionChecklist...)
264		extras.Related = append([]relatedPatternRef(nil), extras.Related...)
265		return extras
266	}
