268	// trimRetrievalExtrasOnce drops one lowest-priority optional tail item. This
269	// gives the caller a useful bounded response even when previews or discovery
270	// pointers consume the budget before any ranked row does.
271	func trimRetrievalExtrasOnce(extras *retrievalTransportExtras) bool {
272		switch {
273		case len(extras.AbstractPreviews) > 0:
274			extras.AbstractPreviews = extras.AbstractPreviews[:len(extras.AbstractPreviews)-1]
275			extras.AbstractPreviewsTruncated = true
276		case len(extras.Related) > 0:
277			extras.Related = extras.Related[:len(extras.Related)-1]
278		case len(extras.Hints.ActionChecklist) > 0:
279			extras.Hints.ActionChecklist = extras.Hints.ActionChecklist[:len(extras.Hints.ActionChecklist)-1]
280		case len(extras.Hints.LikelyTestFiles) > 0:
281			extras.Hints.LikelyTestFiles = extras.Hints.LikelyTestFiles[:len(extras.Hints.LikelyTestFiles)-1]
282		case len(extras.Hints.LikelyEditFiles) > 0:
283			extras.Hints.LikelyEditFiles = extras.Hints.LikelyEditFiles[:len(extras.Hints.LikelyEditFiles)-1]
284		case extras.BlindSpot != "":
285			extras.BlindSpot = ""
286		default:
287			return false
288		}
289		return true
290	}
291	
292	// countRetrievalExtrasTrims reports how many steps trimRetrievalExtrasOnce
293	// can apply to extras before it is exhausted.
294	func countRetrievalExtrasTrims(extras retrievalTransportExtras) int {
295		ex := cloneRetrievalTransportExtras(extras)
296		n := 0
297		for trimRetrievalExtrasOnce(&ex) {
298			n++
299		}
300		return n
301	}
302	
303	// smallestTrimStepsThatFit finds the fewest trim steps, between 1 and
304	// maxSteps, whose rendering fits the response budget. Trimming is monotone —
305	// every step only removes content — so once some step count fits, every
306	// larger one fits, and a binary search returns the same state the former
307	// one-step-at-a-time loop reached while rendering O(log n) candidates
308	// instead of O(n). sizeAt must rebuild from pristine inputs so probes are
309	// order-independent. The untrimmed rendering is the caller's job to check
310	// first: step one adds the truncation marker and can grow the output.
311	func smallestTrimStepsThatFit(maxSteps int, sizeAt func(int) (int, error)) (int, bool, error) {
312		if maxSteps < 1 {
313			return 0, false, nil
314		}
315		if size, err := sizeAt(maxSteps); err != nil || size > conversationConceptResponseMaxBytes {
316			return 0, false, err
317		}
318		lo, hi := 1, maxSteps
319		for lo < hi {
320			mid := (lo + hi) / 2
321			size, err := sizeAt(mid)
322			if err != nil {
323				return 0, false, err
324			}
325			if size <= conversationConceptResponseMaxBytes {
326				hi = mid
327			} else {
328				lo = mid + 1
329			}
330		}
331		return lo, true, nil
332	}
333	
334	// boundedRetrievalJSONPayload removes optional extras, then whole tail rows,
335	// until the exact serialization fits. The response_truncated marker is
336	// present during every truncated size check, so the marker itself can never
337	// push the emitted document over budget.
338	func boundedRetrievalJSONPayload(query, branch string, results []unifiedResult, extras retrievalTransportExtras) (map[string]any, error) {
339		allRows := compactUnifiedResults(results, query)
340		extras = cloneRetrievalTransportExtras(extras)
341		extrasSteps := countRetrievalExtrasTrims(extras)
342		build := func(steps int) map[string]any {
343			ex := cloneRetrievalTransportExtras(extras)
344			for i := 0; i < min(steps, extrasSteps); i++ {
345				trimRetrievalExtrasOnce(&ex)
346			}
347			rows := append([]compactUnifiedResult{}, allRows[:len(allRows)-max(steps-extrasSteps, 0)]...)
348			return buildRetrievalJSONPayload(query, branch, rows, ex, steps > 0)
349		}
350		sizeAt := func(steps int) (int, error) {
351			data, err := jsonOutputBytes(build(steps))
352			if err != nil {
353				return 0, err
354			}
355			return len(data), nil
356		}
357		if size, err := sizeAt(0); err != nil {
358			return nil, err
359		} else if size <= conversationConceptResponseMaxBytes {
360			return build(0), nil
361		}
362		steps, ok, err := smallestTrimStepsThatFit(extrasSteps+len(allRows), sizeAt)
363		if err != nil {
364			return nil, err
365		}
366		if !ok {
367			return nil, fmt.Errorf("retrieval response envelope exceeds %d bytes without any result rows", conversationConceptResponseMaxBytes)
368		}
369		return build(steps), nil
370	}
