376	// renderRetrievalRowsText is shared by single-repo and workspace text modes,
377	// keeping the multi-concept proof contract at parity. Every proof line is independently
378	// bounded even though concepts and identifiers already have stricter input
379	// limits.
380	func renderRetrievalRowsText(out io.Writer, results []unifiedResult, qualify retrievalIDQualifier) {
381		if qualify == nil {
382			qualify = identityRetrievalID
383		}
384		for _, result := range results {
385			ex := base.TruncateString(strings.Join(strings.Fields(result.Text), " "), 200)
386			label := result.Source
387			if result.VerificationRequired {
388				label += " verify"
389			}
390			fmt.Fprintf(out, "[%s] %s  %s\n    %s\n", label, qualify(result.ID), unifiedResultLocation(result), ex)
391			printRetrievalCaveats(out, result)
392			if len(result.Concepts) == 0 {
393				continue
394			}
395			concepts, _ := truncateUTF8Bytes(strings.Join(result.Concepts, " | "), 3*1024)
396			fmt.Fprintf(out, "    proof concepts=%s worst_rank=%d rank_sum=%d approximate=%t\n", concepts, result.WorstRank, result.RankSum, result.Approximate)
397			for _, match := range result.ConceptMatches {
398				terms, _ := truncateUTF8Bytes(strings.Join(match.MatchedTerms, ","), 1024)
399				concept, _ := truncateUTF8Bytes(match.Concept, conversationConceptMaxBytes)
400				fmt.Fprintf(out, "    proof concept=%q evidence=%s rank=%d arm=%s matched_terms=%s\n",
401					concept, qualify(match.ConversationID), match.Rank, match.Arm, terms)
402			}
403			if len(result.EvidenceIDs) > 0 {
404				ids := make([]string, len(result.EvidenceIDs))
405				for i, id := range result.EvidenceIDs {
406					ids[i] = qualify(id)
407				}
408				fmt.Fprintf(out, "    evidence_ids=%s\n", strings.Join(ids, ","))
409			}
410		}
411	}
