418	func renderSingleRepoRetrievalText(query string, results []unifiedResult, extras retrievalTransportExtras, truncated bool) []byte {
419		var out bytes.Buffer
420		if len(results) == 0 && !truncated {
421			fmt.Fprintf(&out, "no results for %q\n", query)
422			if extras.BlindSpot != "" {
423				fmt.Fprintln(&out, extras.BlindSpot)
424			}
425		}
426		hints := extras.Hints
427		for _, file := range hints.LikelyEditFiles {
428			fmt.Fprintf(&out, "edit_file %s\n", file)
429		}
430		for _, file := range hints.LikelyTestFiles {
431			fmt.Fprintf(&out, "test_file %s\n", file)
432		}
433		for _, action := range hints.ActionChecklist {
434			fmt.Fprintf(&out, "action %s %s: %s\n", action.File, action.Symbol, action.Action)
435		}
436		renderRetrievalRowsText(&out, results, nil)
437		for _, pattern := range extras.Related {
438			fmt.Fprintf(&out, "related [%s] %s  %s\n", pattern.Type, pattern.ID, pattern.Title)
439		}
440		previews, previewCut := filteredAbstractPreviewsForResults(extras.AbstractPreviews, results)
441		for _, preview := range previews {
442			text := ""
443			if preview.Overview != nil {
444				text = "  " + strings.Join(strings.Fields(preview.Overview.Text), " ")
445			}
446			fmt.Fprintf(&out, "abstract [%s] %s%s\n", preview.AbstractStatus, preview.SessionRef, text)
447			if preview.AbstractIssue != "" {
448				issue, _ := truncateUTF8Bytes(strings.Join(strings.Fields(preview.AbstractIssue), " "), 1024)
449				fmt.Fprintf(&out, "  automatic enqueue issue: %s\n", issue)
450			}
451		}
452		if extras.AbstractPreviewsTruncated || previewCut {
453			fmt.Fprintln(&out, "abstract previews truncated")
454		}
455		fmt.Fprintf(&out, "response_truncated %t\n", truncated)
456		return out.Bytes()
457	}
