459	func boundedSingleRepoRetrievalText(query string, results []unifiedResult, extras retrievalTransportExtras) ([]byte, error) {
460		extras = cloneRetrievalTransportExtras(extras)
461		extrasSteps := countRetrievalExtrasTrims(extras)
462		render := func(steps int) []byte {
463			ex := cloneRetrievalTransportExtras(extras)
464			for i := 0; i < min(steps, extrasSteps); i++ {
465				trimRetrievalExtrasOnce(&ex)
466			}
467			count := len(results) - max(steps-extrasSteps, 0)
468			return renderSingleRepoRetrievalText(query, results[:count], ex, steps > 0)
469		}
470		if data := render(0); len(data) <= conversationConceptResponseMaxBytes {
471			return data, nil
472		}
473		steps, ok, err := smallestTrimStepsThatFit(extrasSteps+len(results), func(steps int) (int, error) {
474			return len(render(steps)), nil
475		})
476		if err != nil {
477			return nil, err
478		}
479		if !ok {
480			return nil, fmt.Errorf("retrieval text envelope exceeds %d bytes without any result rows", conversationConceptResponseMaxBytes)
481		}
482		return render(steps), nil
483	}
