504	// qualifyWorkspaceUnifiedResult recursively qualifies every addressable id,
505	// not merely the top-level hit. A nested concept proof, session turn, related
506	// id, or abstract citation can therefore be pasted directly into workspace
507	// get without reconstructing the member namespace.
508	func qualifyWorkspaceUnifiedResult(repoKey, workspaceName string, result unifiedResult) unifiedResult {
509		qualify := func(id string) string { return qualifyWorkspaceAddressableID(repoKey, workspaceName, id) }
510		result.ID = qualify(result.ID)
511		result.SessionRef = qualify(result.SessionRef)
512		result.TargetID = qualify(result.TargetID)
513		result.RelatedIDs = append([]string(nil), result.RelatedIDs...)
514		for i := range result.RelatedIDs {
515			result.RelatedIDs[i] = qualify(result.RelatedIDs[i])
516		}
517		result.EvidenceIDs = append([]string(nil), result.EvidenceIDs...)
518		for i := range result.EvidenceIDs {
519			result.EvidenceIDs[i] = qualify(result.EvidenceIDs[i])
520		}
521		result.ConceptMatches = append([]conceptMatch(nil), result.ConceptMatches...)
522		for i := range result.ConceptMatches {
523			result.ConceptMatches[i].ConversationID = qualify(result.ConceptMatches[i].ConversationID)
524			result.ConceptMatches[i].MatchedTerms = append([]string(nil), result.ConceptMatches[i].MatchedTerms...)
525		}
