120	func TestRetrievalResultExcerptCentersDenseQueryTerms(t *testing.T) {
121		text := strings.Repeat("irrelevant preface ", 50) +
122			"inspect code and inspect context JSON are compact by default; use get for full details " +
123			strings.Repeat("irrelevant suffix ", 50)
124		excerpt := retrievalResultExcerpt(text, "inspect context JSON compact full details", 180)
125		for _, want := range []string{"inspect context", "JSON", "compact", "full details"} {
126			if !strings.Contains(excerpt, want) {
127				t.Fatalf("query-centered excerpt missing %q: %q", want, excerpt)
128			}
129		}
130		if len(excerpt) > 186 { // bounded window plus leading/trailing ellipses
131			t.Fatalf("excerpt is not bounded: %d bytes: %q", len(excerpt), excerpt)
132		}
133		unicodeExcerpt := retrievalResultExcerpt(strings.Repeat("界", 300)+" compact context details", "compact context", 80)
134		if !utf8.ValidString(unicodeExcerpt) {
135			t.Fatalf("excerpt split UTF-8: %q", unicodeExcerpt)
136		}
137		// Unicode lowercase can change byte length (K is three UTF-8 bytes but
138		// lowercases to one-byte k). Search offsets must still point into the
139		// original string and center the actual match.
140		foldedExcerpt := retrievalResultExcerpt(strings.Repeat("K", 100)+" TARGET context details", "target context", 64)
141		if !utf8.ValidString(foldedExcerpt) || !strings.Contains(foldedExcerpt, "TARGET context") {
142			t.Fatalf("case-folded Unicode offset missed the query window: %q", foldedExcerpt)
143		}
144	}
