318				out, err := execute(t, NewRootCommand(opts), tc.args...)
319				if err != nil {
320					t.Fatalf("%s: %v\n%s", strings.Join(tc.args, " "), err, out)
321				}
322				var payload struct {
323					Branch  string          `json:"branch"`
324					Results []unifiedResult `json:"results"`
325				}
