687	// TestGetAndMultiGetExitNonzeroOnAMissingID pins the exit code an agent or a
688	// shell script can actually branch on. `get` and `multi-get` printed
689	// `not found: <id>` and exited 0 -- for a total miss as much as a partial one --
690	// while the sibling verb `show` exited 1 for the same condition, so the only way
691	// to tell a hit from a miss was to parse stdout.
692	//
693	// The partial case is the one worth stating out loud: 1 of 2 found still fails,
694	// because every id in the argument list is a request the caller made and `get`
695	// is the one-id case of `multi-get`. The found item is still printed first.
696	func TestGetAndMultiGetExitNonzeroOnAMissingID(t *testing.T) {
697		repoDir := t.TempDir()
698		env := semanticTestEnv(t, repoDir)
699		runner := semanticFixtureRunner(repoDir, semanticFixtureSnapshot("1.0"))
700		now := time.Date(2026, 6, 9, 12, 0, 0, 0, time.UTC)
701		opts := Options{Version: "test", Env: env, Runner: runner, Now: func() time.Time { return now }}
702		storage, err := repoStoragePaths((&cobra.Command{}).Context(), runner, env, repoDir)
703		if err != nil {
704			t.Fatalf("storage: %v", err)
705		}
706		paths := normalizeFactPaths([]string{"architecture.data.flow"})
707		fact := factRecord{
708			ID:        factRecordID("exit codes are a contract", paths),
709			Text:      "exit codes are a contract",
710			Paths:     paths,
711			Branch:    "feature",
712			Status:    factStatusActive,
713			UpdatedAt: now,
714		}
715		if err := factstore.Write(storage.BrainDir, "feature", []factRecord{fact}); err != nil {
716			t.Fatalf("write facts: %v", err)
717		}
718	
719		// A hit still exits 0, or the gate is just "always fail".
720		if out, err := execute(t, NewRootCommand(opts), "get", fact.ID); err != nil {
721			t.Fatalf("get on a present id must succeed: %v\n%s", err, out)
722		}
723		if out, err := execute(t, NewRootCommand(opts), "multi-get", fact.ID); err != nil {
724			t.Fatalf("multi-get on a present id must succeed: %v\n%s", err, out)
725		}
726	
727		// A total miss, the case `show` already got right.
728		out := executeExpectingMissing(t, NewRootCommand(opts), "get", "fact:d7bc8dd14ad31da3f66b9ccf")
729		if !strings.Contains(out, "not found: fact:d7bc8dd14ad31da3f66b9ccf") {
730			t.Fatalf("the miss stopped being readable on the way to the exit code:\n%s", out)
731		}
732	
733		// A partial hit: the found item is emitted, and the command still fails.
734		partial := executeExpectingMissing(t, NewRootCommand(opts), "multi-get", fact.ID, "fact:absent")
735		if !strings.Contains(partial, fact.ID) {
736			t.Fatalf("a partial hit withheld the item it did find:\n%s", partial)
737		}
738		if !strings.Contains(partial, "not found: fact:absent") {
739			t.Fatalf("a partial hit did not name the id it missed:\n%s", partial)
740		}
741	
742		// The JSON body survives the nonzero exit too -- the exit code adds a
743		// signal, it does not replace the payload.
744		jsonOut := executeExpectingMissing(t, NewRootCommand(opts), "multi-get", fact.ID, "fact:absent", "--json")
745		var payload struct {
746			Results []unifiedResult `json:"results"`
747			Missing []string        `json:"missing"`
748		}
749		if err := json.Unmarshal([]byte(jsonOut), &payload); err != nil {
750			t.Fatalf("decode multi-get JSON: %v\n%s", err, jsonOut)
751		}
752		if len(payload.Results) != 1 || len(payload.Missing) != 1 || payload.Missing[0] != "fact:absent" {
753			t.Fatalf("unexpected partial payload: %+v", payload)
754		}
755	}
