14	func WriteJSON(cmd *cobra.Command, value any) error {
15		data, err := json.MarshalIndent(value, "", "  ")
16		if err != nil {
17			return err
18		}
19		n, err := fmt.Fprintln(cmd.OutOrStdout(), string(data))
20		if err == nil && n != len(data)+1 {
21			return io.ErrShortWrite
22		}
23		return err
24	}
