26	func WriteText(cmd *cobra.Command, render func(io.Writer)) error {
27		// Stream directly to stdout instead of buffering the whole rendered body:
28		// large multi-get/fact output must not be held in memory in full. The
29		// sticky writer short-circuits after the first failure and preserves the
30		// error, so callers still skip receipt recording when output fails.
31		return WriteTextToWriter(cmd.OutOrStdout(), render)
32	}
33	
34	func WriteTextToWriter(writer io.Writer, render func(io.Writer)) error {
35		out := &StickyErrorWriter{Writer: writer}
36		render(out)
37		return out.Err
38	}
