40	// ValueOrUnset renders an optional string field for human output, making an
41	// absent value explicit instead of printing an empty gap.
42	func ValueOrUnset(value string) string {
43		if value == "" {
44			return "<unset>"
45		}
46		return value
47	}
48	
49	// StickyErrorWriter short-circuits after the first write failure and retains
50	// the error, so streamed renderers can report output failure once at the end.
51	type StickyErrorWriter struct {
52		Writer io.Writer
53		Err    error
54	}
55	
56	func (w *StickyErrorWriter) Write(p []byte) (int, error) {
57		if w.Err != nil {
58			return 0, w.Err
59		}
60		n, err := w.Writer.Write(p)
61		if err == nil && n != len(p) {
62			err = io.ErrShortWrite
63		}
64		if err != nil {
65			w.Err = err
66		}
